'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/segmentedbutton/md-gb-segmented-button.js';
import '@material/web/labs/gb/components/segmentedbutton/md-gb-segmented-button-set.js';
import {SegmentedButtonElement} from '@material/web/labs/gb/components/segmentedbutton/segmented-button-element.js';
import {SegmentedButtonSetElement} from '@material/web/labs/gb/components/segmentedbutton/segmented-button-set-element.js';

/**
 * One segment of a Material Design segmented button set. Wraps <md-gb-segmented-button>.
 * Docs: https://material-web.dev/3.0/components/segmented-button/
 */
export const MdSegmentedButton = createComponent({
  react: React,
  tagName: 'md-gb-segmented-button',
  elementClass: SegmentedButtonElement,
});

export type MdSegmentedButtonProps = React.ComponentProps<typeof MdSegmentedButton>;

/**
 * A Material Design segmented button set. Wraps <md-gb-segmented-button-set>.
 * Docs: https://material-web.dev/3.0/components/segmented-button/
 */
export const MdSegmentedButtonSet = createComponent({
  react: React,
  tagName: 'md-gb-segmented-button-set',
  elementClass: SegmentedButtonSetElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdSegmentedButtonSetProps = React.ComponentProps<typeof MdSegmentedButtonSet>;
